import{c as t,Q as o,j as s,m as n}from"./chunks/framework.BqPkuuVc.js";const a="/assets/bib-allocation-events.CIO5uVZJ.png",r="/assets/bib-allocation-from-events-list.DqAm35L_.png",i="/assets/bib-allocation-rules.D62axaPn.png",l="/assets/bib-allocation-club-order.Bs_VDufq.png",h="/assets/bib-allocation-table.hFdYljwS.png",c="/assets/bib-allocation-columns.DmXl3kSk.png",b="/assets/bib-allocation-per-event-columns.B6z6U8N6.png",d="/assets/bib-allocation-pin-bib.BEKafI45.png",u="/assets/bib-allocation-actions-menu.CHM3MKib.png",g="/assets/bib-allocation-apply.BHDVu3MS.png",p="/assets/bib-allocation-apply-result.L7DaELEM.png",m="/assets/bib-allocation-leave-warning.DWY9mnBK.png",x=JSON.parse('{"title":"Bib numbers","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/bib-numbers.md","filePath":"user/event-setup/bib-numbers.md"}'),w={name:"user/event-setup/bib-numbers.md"};function v(f,e,y,k,_,S){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="bib-numbers" tabindex="-1">Bib numbers <a class="header-anchor" href="#bib-numbers" aria-label="Permalink to &quot;Bib numbers&quot;">​</a></h1><p><strong>Audience:</strong> Organisers numbering bibs for one event or a whole carnival.</p><p>How to give every competitor a <em><a href="./../getting-started/concepts-glossary#the-event-and-its-people">bib</a></em> number, in blocks by class if you want them, the same number across every day they run, and how to bring in numbers decided somewhere else.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p><strong>Allocate bib numbers</strong> works out a number for every competitor across the events you choose, shows you the whole list, and writes it to them when you say so. Someone entered on several days of a <a href="./multi-stage-events">carnival</a> gets <strong>one</strong> number for all of them.</p><ul><li><strong>Nothing is written until you click it.</strong> You can change the rules and look again as often as you like.</li><li><strong>No number is ever given to two people.</strong> If a block&#39;s numbers are already taken, it moves along and says so.</li><li><strong>Relay classes are left alone.</strong> A relay runner&#39;s bib comes from their team (such as <code>42.1</code>), so they never get a number from here. To number a relay class&#39;s teams, use <strong>Assign bibs…</strong> on the <strong>Relay teams</strong> page — see <a href="./relay-events#team-bibs">Team bibs</a>.</li><li><strong>The rules are saved, not the numbers.</strong> Come back later and the allocation is worked out again from the rules and whoever is entered by then, so a late entry isn&#39;t missed.</li></ul><p>Open it from <strong>Competitors → Actions → Allocate bib numbers…</strong>, or from the <strong>Events</strong> list under <strong>Multi-event → Allocate bib numbers…</strong>. The information icon beside the dialog&#39;s title sums up what it does.</p><h2 id="step-1-the-events" tabindex="-1">Step 1: the events <a class="header-anchor" href="#step-1-the-events" aria-label="Permalink to &quot;Step 1: the events&quot;">​</a></h2><p><img src="'+a+'" alt="Bib numbers - select events: a saved allocation picker, the allocation&#39;s name, and a list of events with the three days of an autumn carnival ticked"></p><ol><li><strong>Saved allocation</strong>: <strong>New allocation</strong>, or one you saved before.</li><li><strong>Name</strong> it, so you can find it again.</li><li>Tick <strong>every event these bibs cover</strong>: the days of a <a href="./multi-stage-events">carnival</a>, separate races that share numbers, or just this one. The event you opened it from, and the other days of its carnival, are ticked already.</li><li>Click <strong>Next</strong>.</li></ol><p>Opened from the <strong>Events</strong> list, nothing is ticked to begin with:</p><p><img src="'+r+'" alt="Bib numbers - select events opened from the Events list: a new allocation named Bib numbers 19/02/2026, and five events with none ticked, three of them days of the Autumn carnival and one marked Has run"></p><p>Events dated before today aren&#39;t listed, apart from this one and its carnival&#39;s other days. One that <strong>Has run</strong> is marked: you can still number it, since a bib can&#39;t change a result, but its start lists and results will show the new numbers.</p><h2 id="step-2-the-rules" tabindex="-1">Step 2: the rules <a class="header-anchor" href="#step-2-the-rules" aria-label="Permalink to &quot;Step 2: the rules&quot;">​</a></h2><p><img src="'+i+'" alt="Bib numbers - rules: Everyone else with Order by and Start from, then class blocks for W21E from 1, M21E from 40, W35 ordered by club, and more, each with a range and a count"></p><h3 id="everyone-else" tabindex="-1">Everyone else <a class="header-anchor" href="#everyone-else" aria-label="Permalink to &quot;Everyone else&quot;">​</a></h3><p>To begin with there are no blocks, and <strong>everybody is numbered together</strong>: choose how they&#39;re ordered (<strong>Order by</strong>) and where the numbers <strong>Start from</strong>. For many events that&#39;s all you need.</p><h3 id="class-blocks" tabindex="-1">Class blocks <a class="header-anchor" href="#class-blocks" aria-label="Permalink to &quot;Class blocks&quot;">​</a></h3><p>To give a class its own run of numbers, such as elites from 1, add a block with <strong>Add a class block…</strong>. For each block:</p><ul><li><strong>From</strong> — the first number. Leave it empty to follow on from the block above.</li><li><strong>Order by</strong> — <strong>Surname</strong>, <strong>Ranking then surname</strong> (the count beside it shows how many in the class have a ranking), or <strong>Club then surname</strong>, which hands numbers out club by club in the order you set with <strong>Club order…</strong>.</li><li><strong>No bibs</strong> — gives this class no numbers, and keeps the numbers its people are already wearing out of everyone else&#39;s way. Use it for a class whose bibs are already printed.</li><li>Drag a block, or use the arrows, to change the order; remove it with <strong>×</strong>.</li></ul><p>Each block shows the numbers it will use and how many people are in it. Everyone not in a block is numbered after all the blocks.</p><p><img src="'+l+'" alt="The Club order dialog over the rules: four clubs in a numbered list with drag grips and move arrows, a Sort A to Z button, and Cancel and Save"></p><p><strong>Club order…</strong> sets the order the clubs are numbered in, for every block ordered by club: drag a club into place, use the arrows, or <strong>Sort A→Z</strong>. A club not on the list is numbered after the ones that are.</p><p><strong>Someone in two classes</strong> (W21E on Saturday, W21A on Sunday) is numbered in whichever of their classes comes <strong>first</strong> in your block list, so dragging a block up decides that. A block can then read <em>in a block above: 12</em>: its entrants were numbered higher up, not missing.</p><p>Click <strong>Next</strong>.</p><h2 id="step-3-the-allocation" tabindex="-1">Step 3: the allocation <a class="header-anchor" href="#step-3-the-allocation" aria-label="Permalink to &quot;Step 3: the allocation&quot;">​</a></h2><p><img src="'+h+'" alt="Bib numbers - allocation: a strip reading Blocks moved (1) and Relay classes skipped (1), then a table of bib, competitor, club, block and card, numbered 1 to 6 in W21E and from 40 in M21E"></p><p>One row per person, with their bib, club, block and card. For a single event, its class, course and start time are shown too; for several, those columns are under the column button, along with <strong>Ranking</strong>, <strong>Person ID</strong>, <strong>Matched by</strong> (how the person was recognised across events) and <strong>Status</strong>. The strip above the table counts anything worth knowing, such as a block that had to move, a relay class skipped, or a class you excluded with <strong>No bibs</strong>. Click <strong>Show all</strong> for the details.</p><p><img src="'+c+'" alt="The column menu of the allocation table: Bib and Competitor always shown, Club, Block and Card ticked, and Ranking, Person ID, Matched by, Status and each event&#39;s class, course and start unticked"></p><p><img src="'+b+'" alt="The allocation table with the first and second days&#39; class and start columns turned on beside each person&#39;s bib, club, block and card"></p><p>Every row starts ticked, and the count of ticked rows is in the dialog&#39;s title bar. <strong>Select all</strong> and <strong>Select none</strong> are above the table: untick anyone you want to leave alone, because the write and the exports under <strong>Actions</strong> cover only the ticked rows.</p><ul><li><p><strong>Change one person&#39;s number</strong> by clicking their <strong>Bib</strong> cell and typing. That pins it, and a pin icon appears beside the number: the rules work around it next time. Clear the cell to unpin it.</p><p><img src="'+d+'" alt="The allocation table with the first person&#39;s Bib cell open for typing, and the third person&#39;s bib 3 showing a pin icon"></p></li><li><p><strong>People matched across events</strong>: Manager decides who is the same person by their IOF ID, then their registration number, then their card (never a <a href="./../running-the-event/hire-items">hire card</a>), then their name and club. Two people it can&#39;t tell apart, such as two with the same name and club, are never merged; they&#39;re counted under <strong>Duplicates</strong> in the strip above the table, for you to check.</p></li></ul><h3 id="writing-the-numbers" tabindex="-1">Writing the numbers <a class="header-anchor" href="#writing-the-numbers" aria-label="Permalink to &quot;Writing the numbers&quot;">​</a></h3><p><img src="'+u+'" alt="The allocation&#39;s Actions menu: Write these bibs to the competitors, Save these rules, Export PDF, Export CSV one row per event, Export CSV one row per person, and Export JSON"></p><p><strong>Actions → Write these bibs to the competitors…</strong> shows how many people and events it will write to — warning you if one of the events has already run — then writes when you click <strong>Apply</strong>. <strong>What happened</strong> then counts the bibs <strong>Written</strong>, those <strong>Already set</strong> to that number, and any <strong>Skipped</strong>. Anyone it couldn&#39;t write is listed, to number by hand.</p><p><img src="'+g+'" alt="The Write the bib numbers confirmation: This writes a bib number to 47 people, across 3 events, with Cancel and Apply"></p><p><img src="'+p+'" alt="After writing: What happened, with Written 105, Already set 18 and Skipped 18, and a Close button"></p><p><strong>Actions → Save these rules</strong> keeps the allocation to come back to. Closing without saving, or without writing, asks first and says which of the two you haven&#39;t done.</p><p><img src="'+m+'" alt="The Leave without finishing? prompt: these rules have not been saved and these bib numbers have not been written, with Cancel and Leave"></p><h3 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h3><p><strong>Actions</strong> also has:</p><ul><li><strong>Export PDF</strong> — the table as shown, for the bib table on the day.</li><li><strong>Export CSV, one row per person</strong> — for the printer, or a spreadsheet.</li><li><strong>Export CSV, one row per event</strong> — each person&#39;s number, class and start time per event.</li><li><strong>Export JSON</strong>.</li></ul><p>Both CSVs always include each event&#39;s class, course and start time, whichever columns are showing, so the sheet you hand the bib printer doesn&#39;t depend on how your table was set up.</p><h2 id="coming-back-to-a-saved-allocation" tabindex="-1">Coming back to a saved allocation <a class="header-anchor" href="#coming-back-to-a-saved-allocation" aria-label="Permalink to &quot;Coming back to a saved allocation&quot;">​</a></h2><p>Choose it under <strong>Saved allocation</strong>. Two buttons then replace <strong>Next</strong>:</p><ul><li><strong>View bibs</strong> shows the numbers the competitors are <strong>wearing now</strong>, including any changed by hand since, for exporting. Nothing can be written or pinned from this view. Somebody wearing different numbers at different events is counted in the strip above the table.</li><li><strong>Reallocate</strong> goes to the rules and works the numbers out again.</li></ul><p>Deleting a saved allocation removes the rules only. Numbers already written stay on the competitors.</p><h2 id="importing-numbers-from-a-file" tabindex="-1">Importing numbers from a file <a class="header-anchor" href="#importing-numbers-from-a-file" aria-label="Permalink to &quot;Importing numbers from a file&quot;">​</a></h2><p>When the numbers were decided somewhere else, such as last year&#39;s spreadsheet or a printed sheet, use <strong>Events list → Multi-event → Import bib numbers…</strong>:</p><ol><li>Tick the events the numbers are for.</li><li>Choose the <strong>CSV</strong> file and map its columns: the bib, and at least one way to find the person (person ID, IOF ID, competitor ID, card or name). A column naming the event makes a row apply to that event only.</li><li>Check what will be written: how many bibs, from how many rows, and any rows that reached nobody.</li><li>Click <strong>Write these bibs</strong>.</li></ol><p>A file only ever <strong>gives</strong> numbers. A blank bib, or a person the file doesn&#39;t mention, is left as it is, so a sheet for one class doesn&#39;t clear everyone else&#39;s. Numbers are written exactly as the file has them (<code>007</code> stays <code>007</code>). Unlike an allocation, a file <em>can</em> give two people one number; if it does, Manager tells you who, so you can fix the file.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a></li><li><a href="./multi-stage-events">Multi-stage events</a></li><li><a href="./relay-events">Relay events</a></li><li><a href="./start-draw">Drawing start times</a> — the start list, which can show each competitor&#39;s bib</li><li><a href="./import-event-data">Importing event data</a></li><li><a href="./../reference/audit-trail">Audit trail</a> — bibs written here are recorded with the source <strong>Bib allocation</strong></li></ul>',53)])])}const A=t(w,[["render",v]]);export{x as __pageData,A as default};
